import { buyAndHold } from "@/lib/backtest/baseline";
import type { Bar } from "@/lib/backtest/bars";
import { backtest, costShare, type Params, type Run } from "@/lib/backtest/strategy";
import { honestyChecks } from "@/lib/backtest/shuffle";
import {
  maxDrawdown,
  returnOverDrawdown,
  timeUnderWater,
  totalReturn,
} from "@/lib/backtest/metrics";
import { neighbours } from "@/lib/backtest/params";
import { outOfSample, splitIndex, tune } from "@/lib/backtest/split";

/**
 * The artefact of the course: a report generated by the code from the run it describes.
 * A report typed by hand drifts from its run. This one cannot, and it carries its own
 * limits section, because a report without one says something about its author.
 */
export type ReportInput = {
  symbol: string;
  bars: Bar[];
  params: Params;
  pulledAt: string;
  /** Distinct parameter sets in the run log for this symbol. */
  paramSetsTried: number;
  /** When the rule was written down, from PLAN.md. */
  statedOn: string;
  /** Where the bars came from: the API, or the mock fixture. */
  source: "EODHD /eod" | "mock fixture";
};

export function buildReport(input: ReportInput): string {
  const { symbol, bars, params, pulledAt } = input;
  const run = backtest(bars, params);
  const charge = params.costBps + params.slippageBps;
  const control = buyAndHold(bars.slice(params.slow - 1), charge);
  const first = bars[0].date;
  const last = bars[bars.length - 1].date;
  const share = costShare(run);
  const split = splitIndex(bars);
  const { best, tried } = tune(bars, split, params);
  const inSample = backtest(bars.slice(0, split), best);
  const oos = outOfSample(bars, best, split);
  const checks = honestyChecks(bars, params);
  const fill =
    params.fill === "next-open"
      ? "the next bar's open"
      : "the signal bar's close (a price nobody had in time)";

  const lines = [
    `# Backtest report: ${symbol}, ${params.fast}/${params.slow} moving-average rule`,
    "",
    "> A historical simulation, not advice. Nobody traded these results, and the author is",
    "> not a licensed adviser.",
    "",
    "## Claim",
    "",
    `Under a cost of ${params.costBps} bps a trade, ${params.slippageBps} bps of slippage against`,
    `each trade and fills at ${fill}, on ${bars.length} daily bars of ${symbol} (${first} to ${last},`,
    `adjusted close, ${input.source}, pulled ${pulledAt.slice(0, 10)}), a rule stated on ${input.statedOn} —`,
    `hold ${symbol} while its ${params.fast}-day average is above its ${params.slow}-day average —`,
    "would have produced the results below.",
    "",
    "## Parameters",
    "",
    "```json",
    JSON.stringify(params, null, 2),
    "```",
    "",
    "## Data",
    "",
    `- Symbol: ${symbol}`,
    `- Bars: ${bars.length}, ${first} to ${last}, daily`,
    "- Returns and signals on `adjusted_close`; fills on raw prices",
    input.source === "mock fixture"
      ? "- Source: `fixtures/eod/SPY.US.json` in mock mode — invented prices in EODHD's shape, not market data"
      : `- Vendor: EODHD /eod, pulled ${pulledAt.slice(0, 10)} and cached`,
    "",
    "## Assumptions",
    "",
    `- Fill: ${fill}`,
    `- Cost: ${params.costBps} bps a trade; slippage: ${params.slippageBps} bps, always against the trade`,
    `- Universe: ${symbol} alone; a single index fund holds its failures rather than omitting them`,
    "- One unit held or none; no leverage, no shorting",
    "",
    `## Results, ${run.dates[0]} to ${run.dates[run.dates.length - 1]}`,
    "",
    "Both lines start on the first bar where the slow average exists, on the same costs.",
    "",
    "| | Strategy | Buy and hold |",
    "|---|---:|---:|",
    `| Gross return | ${pct(totalReturn(run.gross))} | ${pct(totalReturn(control.gross))} |`,
    `| Net return | ${pct(totalReturn(run.net))} | ${pct(totalReturn(control.net))} |`,
    `| Cost as share of gross | ${share.ofGross === null ? "no gross gain" : plain(share.ofGross)} | — |`,
    `| Max drawdown | ${pct(maxDrawdown(run.net))} | ${pct(maxDrawdown(control.net))} |`,
    `| Time under water | ${underWater(run.net)} | ${underWater(control.net)} |`,
    `| Return / max drawdown | ${ratio(returnOverDrawdown(run.net))} | ${ratio(returnOverDrawdown(control.net))} |`,
    `| Trades | ${run.trades.length} | ${control.trades} |`,
    `| Time in market | ${plain(run.timeInMarket)} | 100% |`,
    "",
    "## Robustness",
    "",
    `- In-sample: ${first} to ${bars[split - 1].date}; ${tried.length} parameter sets tried; best ${best.fast}/${best.slow}, net ${pct(totalReturn(inSample.net))}.`,
    `- Out-of-sample, run once with ${best.fast}/${best.slow}: ${bars[split].date} to ${last}, net ${pct(totalReturn(oos.net))}.`,
    `- Parameter sets tried on ${symbol} according to the run log: ${input.paramSetsTried}.`,
    "",
    "| Fast / slow | Net return | Trades |",
    "|---|---:|---:|",
    ...neighbours(params).map((p, i) => {
      const r = backtest(bars, p);
      return `| ${p.fast} / ${p.slow}${i === 0 ? " (chosen)" : ""} | ${pct(totalReturn(r.net))} | ${r.trades.length} |`;
    }),
    "",
    "## Tests",
    "",
    "Run on this data when the report was generated:",
    "",
    `- Future mutation (signals through bar k unchanged when later bars are nonsense): ${passed(checks.futureMutation)}`,
    `- Truncation (signals and positions through bar k unchanged by later data): ${passed(checks.truncation)}`,
    `- Fill range (every fill inside its bar's low-to-high, ${checks.fillRange.fills} fills): ${passed(checks.fillRange.passed)}`,
    `- Shuffle, a null test for time structure, not for leaks: ${pct(checks.shuffle.real)} in the real order, ${pct(checks.shuffle.shuffled)} shuffled (seed 42)`,
    "",
    "## Not tested",
    "",
    `- History: ${first} to ${last}, ${bars.length} bars. Regimes not in the sample: 2008, 2020, 2022, and every rate cycle before it. Max drawdown and time under water describe this window, not the rule.`,
    "- Walk-forward over several periods: one year holds one split, not several.",
    `- Other instruments, and a stock-picking universe with its delisted names: the rule ran on ${symbol} only.`,
    "- Whether anyone would have followed the rule through its worst stretch.",
    "",
  ];
  return lines.join("\n");
}

function pct(fraction: number, digits = 2): string {
  const v = fraction * 100;
  return `${v > 0 ? "+" : v < 0 ? "−" : ""}${Math.abs(v).toFixed(digits)}%`;
}

/** A share of something, which has no direction: 0.61 is 61%. */
function plain(fraction: number): string {
  return `${(fraction * 100).toFixed(0)}%`;
}

function ratio(v: number | null): string {
  return v === null ? "no drawdown" : v.toFixed(2);
}

function underWater(curve: Run["net"]): string {
  const t = timeUnderWater(curve);
  return t.bars === 0 ? "0 bars" : `${t.bars} bars${t.recovered ? "" : ", not recovered"}`;
}

function passed(ok: boolean): string {
  return ok ? "passed" : "FAILED";
}
